import { createReadStream, type ReadStream } from 'node:fs';
import { mkdir, readdir, readFile, rename, rm, stat, writeFile } from 'node:fs/promises';
import path from 'node:path';

/**
 * Where files live. Keys are generated by the server - never a path a
 * visitor typed - and start with their visibility: `public/…` (portfolio
 * media, served to anyone) or `private/…` (client references, served only
 * to the signed-in owner). The disk adapter is the one used today; an
 * object-storage adapter would implement the same five methods.
 */
export interface Storage {
  put(key: string, data: Buffer): Promise<void>;
  read(key: string): Promise<Buffer>;
  stream(key: string): ReadStream;
  size(key: string): Promise<number | null>;
  delete(key: string): Promise<void>;
  /** every key under a prefix ("public/works") - for orphan cleanup */
  list(prefix: string): Promise<string[]>;
}

const KEY = /^(public|private|tmp)\/[a-z0-9][a-z0-9/_.-]*$/;

export function assertKey(key: string) {
  if (!KEY.test(key) || key.includes('..') || key.includes('//')) throw new Error(`Refusing an unsafe storage key: ${JSON.stringify(key)}`);
}

export function diskStorage(root: string): Storage {
  const abs = path.resolve(root);
  const at = (key: string) => {
    assertKey(key);
    const p = path.resolve(abs, ...key.split('/'));
    // belt and braces: whatever the key, the file is inside the root
    if (!p.startsWith(abs + path.sep)) throw new Error('Refusing a key outside storage');
    return p;
  };
  return {
    async put(key, data) {
      const p = at(key);
      await mkdir(path.dirname(p), { recursive: true });
      // write beside, then rename: a reader never sees half a file
      const tmp = `${p}.${process.pid}.${Date.now()}.part`;
      await writeFile(tmp, data, { flag: 'wx' });
      await rename(tmp, p);
    },
    read: (key) => readFile(at(key)),
    stream: (key) => createReadStream(at(key)),
    async size(key) {
      try {
        return (await stat(at(key))).size;
      } catch {
        return null;
      }
    },
    async delete(key) {
      await rm(at(key), { force: true });
    },
    async list(prefix) {
      assertKey(prefix.replace(/\/$/, '') + '/x');
      const dir = path.resolve(abs, ...prefix.split('/').filter(Boolean));
      const out: string[] = [];
      const walk = async (d: string) => {
        let entries;
        try {
          entries = await readdir(d, { withFileTypes: true });
        } catch {
          return;
        }
        for (const e of entries) {
          const p = path.join(d, e.name);
          if (e.isDirectory()) await walk(p);
          else if (!e.name.endsWith('.part')) out.push(path.relative(abs, p).split(path.sep).join('/'));
        }
      };
      await walk(dir);
      return out;
    },
  };
}
